denials.command:
node -e '
const t=require("./docs/playbook/thresholds.json");
for(const [k,v] of Object.entries(t)){ if(typeof v!=="object"||!v)continue; const s=JSON.stringify(v); if(/кноп|chars|символ|слов/.test(v.unit||"")&&/choice|button|C-0[0-9]|C-1|len|max|min/i.test(k)) console.log(k, "=", JSON.stringify(v.value), "|", v.unit, "|", (v.why||v.note||"").slice(0,200));}
'; grep -n -i -E "длин.{0,20}кноп|кноп.{0,40}(длин|слов|символ)|2.{0,3}[–-].{0,3}4 кноп|потолок 4" docs/playbook/rules.md docs/style.md docs/playbook/checks.md | head -30

